<script setup lang="ts">
import {ref,computed,onMounted,onUnmounted,watch} from 'vue'
import {Search,Library,Cloud,Settings,LogOut,Heart,Play,Copy,RefreshCw,ArrowUpRight,Check,Clock,ChevronLeft,ChevronRight,KeyRound,ShieldCheck,Download} from '@lucide/vue'
import {api,setCSRF,time,safeURL,stateNames,type Item,type Task,type Media} from './api'
import {copy,type Playback} from './players'
import {primaryVideo,preferredTask,copyLinkLabel} from './catalog'
import BindingPanel from './BindingPanel.vue'
import AdminPanel from './AdminPanel.vue'
import PlaybackDialog from './PlaybackDialog.vue'
import PlayerButtons from './PlayerButtons.vue'
import {resetPlayback} from './playback-cache'
function windowSafeScroll(){window.scrollTo({top:0,behavior:'smooth'})}
const user=ref<any>(null),initial=ref(true),username=ref(''),password=ref(''),busy=ref(false),notice=ref('')
const tab=ref('catalog'),items=ref<Item[]>([]),tasks=ref<Task[]>([]),favorites=ref<string[]>([]),status=ref<any>({sync:{},source:{}}),binding=ref<any>({state:'unbound'})
const onlyCompleted=ref(false),actorSearch=ref(''),avatars=ref<Record<string,string>>({})
const search=ref(''),sort=ref('score'),actor=ref(''),confirmation=ref('all'),onlyFavorites=ref(false),page=ref(1),detail=ref<Item|null>(null),playback=ref<Playback|null>(null)
const accountDialog=ref(false),oldPassword=ref(''),newPassword=ref(''),ticketHistory=ref<any[]>([])
let timer:ReturnType<typeof setTimeout>|undefined,disposed=false,noticeTimer:ReturnType<typeof setTimeout>|undefined
const stateLabels:Record<string,string>={unbound:'未绑定115',ok:'115连接正常',invalid:'115登录失效',unreachable:'115暂不可达'}
function notify(text:string){notice.value=text;clearTimeout(noticeTimer);noticeTimer=setTimeout(()=>notice.value='',7000)}
async function action(fn:()=>Promise<void>){busy.value=true;try{await fn()}catch(e){notify((e as Error).message)}finally{busy.value=false}}
function expire(){resetPlayback();user.value=null;tab.value='catalog';items.value=[];tasks.value=[];favorites.value=[];detail.value=null;playback.value=null;accountDialog.value=false;binding.value={state:'unbound'};status.value={sync:{},source:{}};clearTimeout(timer);setCSRF('')}
async function refresh(){
 const [s,b,t]=await Promise.all([api('/catalog/status'),api('/me/115'),api('/me/tasks')]);if(!user.value)return
 const changed=s.sync.last_success!==status.value.sync.last_success
 if(binding.value.revision!==b.revision)resetPlayback()
 status.value=s;binding.value=b;tasks.value=t
 if(changed){const data=await api('/catalog/items');if(user.value){items.value=data.items;avatars.value=data.avatars||{}}}
}
async function poll(){if(!user.value||disposed)return;try{await refresh()}catch{}finally{if(user.value&&!disposed)timer=setTimeout(poll,document.hidden?15000:active.value?1000:5000)}}
async function load(){const [data,f]=await Promise.all([api('/catalog/items'),api('/me/favorites')]);items.value=data.items;avatars.value=data.avatars||{};favorites.value=f;await refresh();clearTimeout(timer);timer=setTimeout(poll,5000)}
async function login(){await action(async()=>{const d=await api('/auth/login','POST',{username:username.value,password:password.value});password.value='';user.value=d.user;setCSRF(d.csrf);await load()})}
async function logout(){await action(async()=>{await api('/auth/logout','POST');expire()})}
const readyCodes=computed(()=>new Set(tasks.value.filter(t=>t.state==='completed'&&t.files.length).map(t=>t.resource)))
const actorCounts=computed(()=>{const counts=new Map<string,number>();for(const i of items.value)for(const a of i.actors)counts.set(a,(counts.get(a)||0)+1);return [...counts].filter(([a])=>a.toLowerCase().includes(actorSearch.value.toLowerCase())).sort((a,b)=>b[1]-a[1]||a[0].localeCompare(b[0],'ja'))})
const actors=computed(()=>[...new Set(items.value.flatMap(i=>i.actors))].sort((a,b)=>a.localeCompare(b,'zh')))
const filtered=computed(()=>{
 const terms=search.value.toLowerCase().trim().split(/\s+/).filter(Boolean)
 const list=items.value.filter(i=>{const hay=[i.code,i.code.replaceAll('-',''),i.title,i.title_zh||'',i.maker||'',...i.actors].join(' ').toLowerCase();return terms.every(t=>hay.includes(t))&&(!onlyCompleted.value||readyCodes.value.has(i.code))&&(!actor.value||i.actors.includes(actor.value))&&(!onlyFavorites.value||favorites.value.includes(i.code))&&(confirmation.value==='all'||Boolean(i.pending)===(confirmation.value==='pending'))})
 return list.sort((a,b)=>sort.value==='score'?(b.score||0)-(a.score||0):sort.value==='date'?(b.date||'').localeCompare(a.date||''):sort.value==='code'?a.code.localeCompare(b.code):(b.added_at||0)-(a.added_at||0))
})
const pageCount=computed(()=>Math.max(1,Math.ceil(filtered.value.length/24)))
const shown=computed(()=>filtered.value.slice((page.value-1)*24,page.value*24))
const active=computed(()=>tasks.value.filter(t=>['submitting','unknown','downloading'].includes(t.state)).length)
watch([search,sort,actor,confirmation,onlyFavorites,onlyCompleted],()=>page.value=1)
watch([detail,playback,accountDialog],([d,p,a])=>{document.body.style.overflow=d||p||a?'hidden':''})
watch(tab,()=>window.scrollTo({top:0,behavior:'instant'}),{flush:'post'})
function taskFor(code:string){return preferredTask(tasks.value,code)}
watch(pageCount,n=>{if(page.value>n)page.value=n})
async function favorite(i:Item){await action(async()=>{const exists=favorites.value.includes(i.code);await api('/me/favorites/'+encodeURIComponent(i.code),exists?'DELETE':'PUT');favorites.value=exists?favorites.value.filter(c=>c!==i.code):[...favorites.value,i.code]})}
async function submit(i:Item,index=0){if(binding.value.state==='unbound'||binding.value.state==='invalid'){tab.value='binding';detail.value=null;notify('请先绑定自己的115账号');return}await action(async()=>{const result=await api('/me/tasks','POST',{code:i.code,link_index:index});await refresh();clearTimeout(timer);timer=setTimeout(poll,1000);notify(result.state==='completed'?'此作品已离线，可直接播放':'任务已提交，正在检查115完成状态')})}
function cardPlay(i:Item){const t=taskFor(i.code);if(t&&['completed','missing'].includes(t.state)){playTask(t);return}if(t&&['failed','cancelled'].includes(t.state)){tab.value='tasks';return}if(t&&['submitting','unknown','downloading'].includes(t.state)){tab.value='tasks';return}submit(i)}
function playTask(t:Task){const f=primaryVideo(t);if(!f){notify('任务尚未找到视频，请稍后刷新');return}prepare(t,f)}
async function prepare(t:Task,f:Media){await action(async()=>{playback.value=await api('/playback/tickets','POST',{task_id:t.id,pickcode:f.pickcode})})}
async function retry(t:Task){if(!confirm('重新处理此任务？仅在确认文件失效时清理对应离线记录，不删除网盘文件。'))return;await action(async()=>{await api('/me/tasks/'+t.id+'/retry','POST');await refresh()})}
async function cancelTask(t:Task){if(!confirm('取消此离线任务？已生成的115文件会保留。'))return;await action(async()=>{await api('/me/tasks/'+t.id+'/cancel','POST');await refresh();notify('任务已取消')})}
async function deleteTask(t:Task){const files=['completed','missing'].includes(t.state);if(!confirm(files?'删除 '+t.resource+' 的任务及115对应文件？此操作会删除网盘文件。':'删除此任务记录？'))return;await action(async()=>{await api('/me/tasks/'+t.id,'DELETE');await refresh();notify(files?'任务及115对应文件已删除':'任务记录已删除')})}
async function copyText(value:string){try{await copy(value);notify('已复制')}catch(e){notify((e as Error).message)}}
async function openAccount(){accountDialog.value=true;try{ticketHistory.value=await api('/playback/tickets')}catch(e){notify((e as Error).message)}}
function changePassword(){action(async()=>{await api('/auth/password','POST',{old_password:oldPassword.value,password:newPassword.value});oldPassword.value='';newPassword.value='';expire();notify('密码已更新，请重新登录')})}
function keydown(e:KeyboardEvent){if(e.key==='Escape'){detail.value=null;playback.value=null;accountDialog.value=false}if(e.key==='/'&&!['INPUT','TEXTAREA','SELECT'].includes((e.target as HTMLElement)?.tagName)){e.preventDefault();document.querySelector<HTMLInputElement>('#search')?.focus()}}
onMounted(async()=>{window.addEventListener('session-expired',expire);window.addEventListener('keydown',keydown);try{const d=await api('/auth/me');user.value=d.user;setCSRF(d.csrf);await load()}catch(e){if(user.value)notify((e as Error).message)}finally{initial.value=false}})
onUnmounted(()=>{disposed=true;document.body.style.overflow='';clearTimeout(timer);clearTimeout(noticeTimer);window.removeEventListener('session-expired',expire);window.removeEventListener('keydown',keydown)})
</script>
<template>
 <div v-if="initial" class="loading"><div class="brand-mark">L</div><p>正在打开你的资源库…</p></div>
 <main v-else-if="!user" class="login-screen"><section class="login-art"><div class="brand"><span class="brand-mark">L</span><span>Jasna<span class="accent">·</span>LTX</span></div><div><span class="eyebrow">YOUR PERSONAL COLLECTION</span><h1>收藏所爱。<br>随时开播。</h1><p>一个安静的资源库。<br>同步发现，用自己的115，<br>在喜欢的播放器中继续。</p></div><span class="muted">私人镜像 · 独立账号 · 直连播放</span></section>
 <section class="login-form"><div class="login-card"><span class="eyebrow">WELCOME BACK</span><h2>登录资源库</h2><p class="muted">使用管理员为你创建的账号。</p><form @submit.prevent="login"><label>账号<input v-model="username" autocomplete="username" required placeholder="输入账号"></label><label>密码<input v-model="password" type="password" autocomplete="current-password" required placeholder="输入密码"></label><button class="primary" :disabled="busy">{{busy?'正在登录…':'进入资源库'}} <ArrowUpRight :size="17"/></button></form><p class="hint"><ShieldCheck :size="15"/>站点账号与115账号独立，登录后可扫码绑定。</p></div></section></main>
 <div v-else class="shell"><header class="topbar"><a href="#" @click.prevent="tab='catalog'" class="brand"><span class="source-mark">Jasna-LTX</span><span class="source-name">资源库</span></a><div v-if="tab==='catalog'" class="header-search search-wrap"><Search :size="17"/><input id="search" type="search" enterkeyhint="search" v-model="search" placeholder="搜索番号、标题、演员…" aria-label="搜索资源"><kbd>/</kbd></div><nav aria-label="主导航"><button :class="{selected:tab==='catalog'}" @click="tab='catalog'"><Library :size="17"/>资源库</button><button :class="{selected:tab==='tasks'}" @click="tab='tasks'"><Play :size="17"/>我的任务 <span v-if="active" class="counter">{{active}}</span></button><button :class="{selected:tab==='binding'}" @click="tab='binding'"><Cloud :size="17"/>我的115</button><button v-if="user.role==='admin'" :class="{selected:tab==='admin'}" @click="tab='admin'"><Settings :size="17"/>管理</button></nav><div class="user-tools"><button class="user-button" @click="openAccount">{{user.username}}</button><button class="icon-button" @click="logout" title="退出登录" aria-label="退出登录"><LogOut :size="17"/></button></div></header>
 <div class="status-strip"><div><span class="dot" :class="status.source.ok===true?'good':status.source.ok===false?'bad':''"></span><span>源站{{status.source.ok===true?'可达':status.source.ok===false?'暂不可达':'未检查'}}</span><span class="status-time">检查于 {{time(status.source.checked)}}</span></div><div><span :class="binding.state==='ok'?'green-text':'muted'">{{stateLabels[binding.state]}}</span><span class="separator">/</span><span>{{status.sync.running?'同步中…':'最后同步 '+time(status.sync.last_success)}}</span><button v-if="user.role==='admin'" class="icon-button" :disabled="busy||status.sync.running" title="立即同步" aria-label="立即同步" @click="action(async()=>{await api('/admin/sync-now','POST');await refresh()})"><RefreshCw :size="14" :class="{spin:status.sync.running}"/></button></div></div>
 <div class="portal-layout" :class="{'with-sidebar':tab==='catalog'}"><aside v-if="tab==='catalog'" class="actor-sidebar" aria-label="演员筛选"><div class="side-head"><button :class="{selected:!actor&&!onlyFavorites&&!onlyCompleted}" @click="actor='';onlyFavorites=false;onlyCompleted=false">全部 <span>{{items.length}}</span></button><button :class="{selected:onlyFavorites}" @click="onlyFavorites=!onlyFavorites">想看 <span>{{favorites.length}}</span></button><button :class="{selected:onlyCompleted}" @click="onlyCompleted=!onlyCompleted">已离线 <span>{{readyCodes.size}}</span></button><input v-model="actorSearch" placeholder="筛选演员…" aria-label="搜索演员"></div><div class="actor-list"><button v-for="[name,count] in actorCounts" :key="name" class="actor-entry" :class="{selected:actor===name}" @click="actor=actor===name?'':name"><img v-if="typeof avatars[name]==='string'&&safeURL(avatars[name])" :src="safeURL(avatars[name])" alt="" loading="lazy" referrerpolicy="no-referrer"><span v-else class="actor-avatar">{{name.slice(0,1)}}</span><span class="actor-name">{{name}}</span><small>{{count}}</small></button></div></aside><main class="content" :class="{'catalog-content':tab==='catalog'}"><template v-if="tab==='catalog'">
 <p v-if="status.sync.last_error" class="notice">{{status.sync.last_error}}</p>
 <section class="catalog-toolbar" aria-label="资源筛选"><h1>{{actor|| (onlyFavorites?'想看清单':onlyCompleted?'已离线':'全部作品')}} <small>{{filtered.length}}</small></h1><div class="catalog-controls"><button class="favorite-filter" :class="{selected:onlyCompleted}" @click="onlyCompleted=!onlyCompleted"><Check :size="15"/>已离线 {{readyCodes.size}}</button><button class="favorite-filter" :class="{selected:onlyFavorites}" @click="onlyFavorites=!onlyFavorites"><Heart :size="15"/>想看 {{favorites.length}}</button><select v-model="actor" class="mobile-actors" aria-label="按演员筛选"><option value="">全部演员</option><option v-for="a in actors" :key="a">{{a}}</option></select><select v-model="confirmation" aria-label="确认状态"><option value="all">全部状态</option><option value="confirmed">已确认</option><option value="pending">待确认</option></select><select v-model="sort" aria-label="排序"><option value="code">编号排序</option><option value="added">最近入库</option><option value="date">发行日期</option><option value="score">评分优先</option></select></div></section>
 <section v-if="shown.length" class="cards"><article v-for="i in shown" :key="i.code" :data-code="i.code" class="card"><div class="cover-wrap"><button class="cover-button" @click="detail=i" :aria-label="'查看 '+i.code"><img v-if="safeURL(i.cover)" :src="safeURL(i.cover)" :alt="i.code+' 封面'" loading="lazy" referrerpolicy="no-referrer"><div v-else class="cover-placeholder">{{i.code}}</div></button><button class="code-badge" @click="copyText(i.code)" :aria-label="'复制番号 '+i.code">{{i.code}} <Copy :size="11"/></button><span class="cover-tag" v-if="i.pending">待确认</span><span class="rating" v-if="i.score">★ {{i.score.toFixed(2)}}</span><button class="heart" @click="favorite(i)" :aria-label="favorites.includes(i.code)?'取消想看':'加入想看'" :class="{saved:favorites.includes(i.code)}"><Heart :size="17" :fill="favorites.includes(i.code)?'currentColor':'none'"/></button></div><div class="card-body"><button class="card-title" @click="detail=i">{{i.title_zh||i.title||i.code}}</button><div class="actors tags"><button v-for="a in i.actors.slice(0,3)" :key="a" @click="actor=a">{{a}}</button><button v-if="i.actors.length>3" @click="detail=i">+{{i.actors.length-3}}</button></div><div class="card-meta"><span>{{[i.date,i.maker].filter(Boolean).join(' · ')||'信息待补全'}}</span><button @click="detail=i">详情 ↗</button></div><div class="card-actions"><button class="copy-ed2k" :disabled="!i.links.length" @click="copyText(i.links.find(l=>l.startsWith('ed2k:'))||i.links[0])"><Copy :size="13"/>{{copyLinkLabel(i.links)}}</button><PlayerButtons v-if="taskFor(i.code)?.state==='completed'" :task="taskFor(i.code)!" @fallback="playback=$event" @notice="notify"/><button v-else :disabled="busy||!i.links.length" class="play-button" @click="cardPlay(i)"><Download :size="14"/>{{taskFor(i.code)?stateNames[taskFor(i.code)!.state]:'添加到 115'}}</button><button v-if="taskFor(i.code)?.state!=='completed'" class="more-links" @click="detail=i" aria-label="更多资源链接">•••</button></div></div></article></section>
 <section v-else class="empty"><Library :size="36"/><h2>{{items.length?'没有匹配的作品':'资源库正在等待同步'}}</h2><p>{{items.length?'换个关键词或筛选条件试试。':'管理员可以立即同步；源站异常时会显示具体原因。'}}</p></section>
 <div class="pagination" v-if="filtered.length"><button :disabled="page<=1" @click="page--;windowSafeScroll()"><ChevronLeft :size="16"/>上一页</button><span>{{page}} / {{pageCount}}</span><button :disabled="page>=pageCount" @click="page++;windowSafeScroll()">下一页<ChevronRight :size="16"/></button></div></template>
 <template v-if="tab==='tasks'"><section class="hero"><div><span class="eyebrow">YOUR WATCHLIST</span><h1>个人任务库<span class="accent">.</span></h1><p class="muted">离开页面也会继续检查任务。这里只显示当前115绑定的任务。</p></div><button @click="action(refresh)"><RefreshCw :size="16"/>刷新</button></section><div class="empty" v-if="!tasks.length"><Cloud :size="36"/><h2>还没有离线任务</h2><p>从资源库选择作品，离线到自己的115。</p><button class="primary" @click="tab='catalog'">浏览资源库</button></div><section class="task-list"><article class="task-row" v-for="t in tasks" :key="t.id"><div class="task-symbol"><Check v-if="t.state==='completed'"/><Clock v-else/></div><div class="task-info"><div class="task-title"><strong>{{t.resource}}</strong><span class="pill" :class="t.state==='completed'?'green':''">{{stateNames[t.state]}}</span></div><p>{{t.title}}</p><small v-if="t.error" class="error-text">{{t.error}}</small><small v-else class="muted">更新于 {{time(t.updated)}}</small><progress v-if="['submitting','downloading','unknown'].includes(t.state)" max="100" :value="t.percent"></progress></div><div class="actions"><PlayerButtons v-if="t.files.length&&t.state==='completed'" :task="t" @fallback="playback=$event" @notice="notify"/><button v-else-if="t.files.length" :disabled="busy" @click="playTask(t)">重新检查播放</button><button v-if="['failed','missing','cancelled'].includes(t.state)" :disabled="busy" @click="retry(t)">明确重试</button><button v-if="['submitting','unknown','downloading'].includes(t.state)" :disabled="busy" @click="cancelTask(t)">取消离线</button><button v-else class="danger" :disabled="busy" @click="deleteTask(t)">{{['completed','missing'].includes(t.state)?'删除任务和文件':'删除记录'}}</button><span v-if="t.state==='downloading'">{{Math.floor(t.percent)}}%</span></div></article></section></template>
 <BindingPanel v-if="tab==='binding'" @changed="action(refresh)"/><AdminPanel v-if="tab==='admin'&&user.role==='admin'" @changed="action(refresh)"/>
 </main></div><footer><span><span class="accent">LTX</span> · 你的私人镜像</span><span>数据来自源站快照 · 视频直连115 · v1.0</span></footer></div>
 <div class="toast" role="status" v-if="notice">{{notice}}</div>
 <div v-if="detail" class="overlay" @click.self="detail=null"><section class="dialog detail" role="dialog" aria-modal="true" aria-labelledby="detail-title"><button class="close" @click="detail=null" aria-label="关闭">×</button><span class="eyebrow">{{detail.code}}</span><h2 id="detail-title">{{detail.title_zh||detail.title}}</h2><p class="muted">{{detail.actors.join(' / ')}} · {{detail.date}} · {{detail.maker}}</p><img v-if="safeURL(detail.cover||detail.shot)" class="detail-image" :src="safeURL(detail.cover||detail.shot)" alt="作品图片" referrerpolicy="no-referrer"><p>{{detail.title}}</p><div class="tags"><span v-for="g in detail.genres||[]" :key="g" class="pill">{{g}}</span></div><h3>可用资源 {{detail.links.length}}</h3><div v-for="(l,index) in detail.links" :key="l" class="resource-link"><span>资源 {{index+1}} · {{l.startsWith('magnet:')?'磁力':'ed2k'}}</span><div class="actions"><button @click="copyText(l)">复制</button><button class="primary" :disabled="busy" @click="submit(detail!,index)">离线到115</button></div></div><a v-if="safeURL(detail.url)" :href="safeURL(detail.url)" target="_blank" rel="noopener noreferrer" class="external">查看外部详情 ↗</a></section></div>
 <PlaybackDialog v-if="playback" :playback="playback" @close="playback=null"/>
 <div v-if="accountDialog" class="overlay" @click.self="accountDialog=false"><section class="dialog" role="dialog" aria-modal="true" aria-labelledby="account-title"><button class="close" @click="accountDialog=false" aria-label="关闭">×</button><h2 id="account-title">账号设置</h2><form @submit.prevent="changePassword"><label>原密码<input type="password" v-model="oldPassword" autocomplete="current-password" required></label><label>新密码<input type="password" v-model="newPassword" autocomplete="new-password" minlength="12" required placeholder="至少12位"></label><button class="primary" :disabled="busy"><KeyRound :size="16"/>修改密码并退出所有设备</button></form><h3>有效播放凭证</h3><p class="hint">撤销会阻止后续取链，已获取的115直链由115控制有效期。</p><p class="muted" v-if="!ticketHistory.length">暂无有效凭证</p><div class="file-row" v-for="t in ticketHistory" :key="t.id"><span class="filename">{{t.name}}<small class="muted">到期 {{time(t.expires)}}</small></span><button @click="action(async()=>{await api('/playback/tickets/'+t.id,'DELETE');resetPlayback();ticketHistory=await api('/playback/tickets')})">撤销</button></div></section></div>
</template>
